use anyhow :: { Context , Result } ; use serde :: { Deserialize , Serialize } ; use std :: fs ; use std :: path :: Path ; use super :: * ; use serde_json :: json ; use tempfile :: NamedTempFile ; # [doc = " Load JSON trace from file"] pub fn load_trace (path : impl AsRef < Path >) -> Result < SourceTrace > { let path = path . as_ref () ; let content = fs :: read_to_string (path) . with_context (| | format ! ("Failed to read trace file: {}" , path . display ())) ? ; let trace : SourceTrace = serde_json :: from_str (& content) . with_context (| | format ! ("Failed to parse JSON from: {}" , path . display ())) ? ; Ok (trace) }